from pathlib import Path
import json,re,shutil
root=Path(__file__).resolve().parents[2]
out=Path(__file__).resolve().parent
def rec(**kw): return kw
source='research/notes/levantamiento_dosificacion_san_miguel.md'
recipes=[rec(id=str(i),nombre=n,harina=h,azucar=a,sal=s,levadura=l,estado='Por verificar',fuente=source,notas='Receta de referencia registrada. Origen documental y trazabilidad pendientes.'+(' Un solo ciclo para empanadas y rollos; no duplicar.' if i==4 else '')) for i,(n,h,a,s,l) in enumerate([('Pan casero',6500,400,100,30),('Marraqueta',8000,80,150,30),('Pan francés',7500,80,150,30),('Masa común',5000,150,100,20)],1)]
raw=(root/'docs/thesis/chapters/additional_material/apendices/entrevista_requerimientos.tex').read_text(encoding='utf-8')
qa=re.findall(r'\\textbf\{(\d+)\. (.*?)\}\s*(.*?)(?=\\noindent|%---)',raw,re.S)
interviews=[]
for num,q,a in qa:
 a=re.sub(r'\\par|\\medskip','',a).strip()
 interviews.append(rec(id='E'+num,pregunta=q,respuesta=a,persona='Máxima Peres',fecha='2026-11-08' if num!='14' else '',estado='Confirmado',fuente='docs/thesis/chapters/additional_material/apendices/entrevista_requerimientos.tex',faltantes='Fecha específica del seguimiento no indicada.' if num=='14' else 'Firma o respaldo original por verificar.',notas='Transcripción del apéndice existente; no implica validación experimental.'))
interviews.append(rec(id='E15',pregunta='¿Qué bandas de exceso y déficit acepta para azúcar, sal y levadura en cada receta?',respuesta='',persona='',fecha='',estado='Pendiente',fuente='',faltantes='Respuesta real, persona consultada, fecha y respaldo.',notas='Pregunta de seguimiento propuesta; entrevista aún no realizada.'))
requirements=[]
for i,(name,mi,ma,tol) in enumerate([('Harina',5000,8000,30),('Azúcar',80,400,3),('Sal',100,150,2),('Levadura en polvo',20,30,1)],1):
 requirements.append(rec(id='R'+str(i),nombre='Dosificación de '+name.lower(),ingrediente=name,minimo_observado=mi,maximo_observado=ma,minimo_diseno=None,maximo_diseno=None,tolerancia=tol,estado='Por verificar',tipo='Requisito propuesto',fuente='D-022 / D-024; '+source,verificacion='Ensayos por lote y receta con referencia caracterizada.',notas='Meta de ingeniería adoptada por el estudiante; aceptación de receta y desempeño pendientes.'+(' Meta adicional: media de error absoluto ≤10 g.' if i==1 else '')))
for i,(n,e,t,note,f) in enumerate([('Cuatro ingredientes secos','Confirmado','Requisito confirmado','Harina, azúcar, sal y levadura en polvo. Agua y manteca fuera de alcance.','D-015 / D-016'),('Alimentación por tornillo','Confirmado','Requisito confirmado','Cuatro tornillos comerciales; tolvas diseñadas. Modelos y disponibilidad pendientes.','D-019'),('Tiempo de ciclo','Pendiente','Requisito propuesto','La propietaria no fijó un tiempo numérico aceptable.','Entrevista, pregunta 8'),('Limpieza y desmontaje','Por verificar','Requisito propuesto','Facilitar retiro de partes y residuos; procedimiento y meta por definir.','Entrevista, pregunta 12'),('Espacio y acceso','Pendiente','Requisito propuesto','Medir puesto, paso libre y altura de recarga.','Entrevista, pregunta 11')],5):
 requirements.append(rec(id='R'+str(i),nombre=n,ingrediente='Sistema',minimo_observado=None,maximo_observado=None,minimo_diseno=None,maximo_diseno=None,tolerancia=None,estado=e,tipo=t,fuente=f,verificacion='',notas=note))
alt_source='docs/thesis/chapters/marcopractico/tables/combinaciones_dosificadora.tex'
alternatives=[rec(id='A',nombre='A · Pesaje común',tolvas='Cuatro tolvas independientes',tornillos='Cuatro horizontales',pesaje='Común, celda de punto único',motores='Paso a paso y acople directo',control='Microcontrolador; conversión dedicada',descarga='Directa al recipiente; sin receptor auxiliar',ventajas='Evita transferencia auxiliar.',pendientes='Incrementos pequeños bajo carga, vibración, capacidad con tara y extracción lateral.',costo=None,estado='Por verificar',fuente=alt_source,notas='Configuración de estudio, sin selección definitiva.'),rec(id='B',nombre='B · Pesaje separado horizontal',tolvas='Cuatro tolvas independientes',tornillos='Cuatro horizontales',pesaje='Dos pesajes, celdas de punto único',motores='CC con reducción en harina; paso a paso en menores',control='Microcontrolador; adquisición de ambos pesajes',descarga='Harina directa; receptor auxiliar basculante para menores',ventajas='Separa escalas de pesaje; referencia para predimensionamiento.',pendientes='Retención, basculamiento, pesaje bajo carga, fichas y espacio.',costo=None,estado='Por verificar',fuente=alt_source,notas='Referencia preliminar (D-023), no selección final ni desempeño demostrado.'),rec(id='C',nombre='C · Pesaje separado vertical',tolvas='Depósito compartimentado',tornillos='Cuatro verticales descendentes',pesaje='Dos pesajes, celdas de punto único',motores='Paso a paso y acople directo',control='PLC, transmisores y HMI compatibles',descarga='Harina directa; apertura inferior del auxiliar',ventajas='Variante de distribución y mando para contrastar.',pendientes='Altura de recarga, extracción vertical, apertura, retención y costo.',costo=None,estado='Por verificar',fuente=alt_source,notas='Configuración de estudio, sin selección definitiva.')]
components=[rec(id='C'+str(i),nombre=n,funcion=f,modelo='',cantidad=q,estado=e,fuente=fu,pendientes=p,costo=None) for i,(n,f,q,e,fu,p) in enumerate([('Tolvas','Almacenar ingredientes',4,'Por verificar','D-019','Capacidad, densidad aparente, geometría y limpieza.'),('Tornillos alimentadores','Alimentar los cuatro ingredientes',4,'Confirmado','D-019','Diámetro, paso, longitud, disponibilidad y ficha comercial.'),('Celdas de carga','Medir cantidad dosificada',None,'Pendiente','A-004','Pesaje común/separado, capacidad con tara, sensibilidad y montaje.'),('Compuertas / vaciado auxiliar','Transferir ingredientes menores',None,'Por verificar',alt_source,'Solo donde lo requiera la alternativa; no sustituye tornillos. Retención y accionamiento.'),('Motores','Accionar tornillos',4,'Pendiente','A-004 / D-019','Par de arranque, curva par-velocidad, corriente, reducción y régimen.'),('Recipiente receptor','Recibir los ingredientes',1,'Por verificar','context/PROJECT_CONTEXT.md','Canoa ovalada 20 L. Exteriores aproximados 515 × 353 × 182 mm; medir abertura útil, base y tara. No acreditada aptitud alimentaria.')],1)]
decisions=[]
dr=(root/'context/DECISIONS.md').read_text(encoding='utf-8')
for match in re.finditer(r'### ((?:D|A)-\d+) — (.*?)(?=\n### |\n## |\Z)',dr,re.S):
 id,titlebody=match.groups(); title,_,body=titlebody.partition('\n'); st=re.search(r'\*\*Estado:\*\* (.*)',body)
 if not st or 'Reemplazada' in st[1] or 'Resuelto' in st[1]: continue
 txt=re.sub(r'\*\*|`','',body).strip()
 decisions.append(rec(id=id,nombre=title,estado='Pendiente' if 'NO DECIDIDO' in st[1] else 'Confirmado',detalle=txt,fuente='context/DECISIONS.md',validacion='No cerrar sin evidencia o decisión explícita.' if id.startswith('A') else 'Conservar los límites de aprobación y alcance indicados.'))
paths=[source,'docs/thesis/chapters/additional_material/apendices/entrevista_requerimientos.tex','context/DECISIONS.md','context/PROJECT_CONTEXT.md',alt_source,'research/notes/alternativas_diseno_san_miguel_2026-11-11.md']
sources=[]
(out/'references').mkdir(exist_ok=True)
for i,p in enumerate(paths,1):
 name=Path(p).name; shutil.copyfile(root/p,out/'references'/name)
 titles=['Levantamiento de dosificación manual','Entrevista de requerimientos','Decisiones vigentes y abiertas','Contexto del proyecto','Combinaciones de diseño A, B y C','Análisis de alternativas de diseño']
 sources.append(rec(id='F'+str(i),nombre=titles[i-1],ruta=p,estado='Confirmado',notas='Copia de referencia del proyecto al 15/11/2026; conserva las validaciones pendientes del original.',archivo='/referencias/'+name))
data=rec(recetas=recipes,requisitos=requirements,alternativas=alternatives,componentes=components,entrevistas=interviews,decisiones=decisions,fuentes=sources)
(out/'seed.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
(out/'.openai/hosting.json').write_text(json.dumps(rec(project_id='appgprj_6af9e89a50448191bc7ce23c02c3f261',d1='DB',r2='BUCKET')),encoding='utf-8')
print(f'{len(interviews)} preguntas, {len(decisions)} decisiones y {len(sources)} fuentes preparadas.')
